import { createChange, createController, definePrimitive, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

type SidebarCollapsedChangeReason = "trigger-press" | "imperative"

type SidebarOptions = {
  collapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean, details: ChangeDetails<SidebarCollapsedChangeReason>) => void
  controller?: SidebarController
}

interface SidebarController {
  setCollapsed: (collapsed: boolean, options?: ChangeOptions<SidebarCollapsedChangeReason>) => boolean | undefined
  collapse: (options?: ChangeOptions<SidebarCollapsedChangeReason>) => boolean | undefined
  expand: (options?: ChangeOptions<SidebarCollapsedChangeReason>) => boolean | undefined
  toggle: (options?: ChangeOptions<SidebarCollapsedChangeReason>) => boolean | undefined
}

function reasonOf(options: unknown): { reason: SidebarCollapsedChangeReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<SidebarCollapsedChangeReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

const sidebar = definePrimitive({
  name: "sidebar",
  options: { collapsed: "boolean", defaultCollapsed: "boolean", onCollapsedChange: "callback", controller: "value" },
  state: (options: SidebarOptions) => ({ collapsed: options.collapsed ?? options.defaultCollapsed ?? false }),
  sync: (options) => (options.collapsed === undefined ? {} : { collapsed: options.collapsed }),
  controlled: ["collapsed"],
  api: (context) => {
    const change = createChange(context)
    const setCollapsed = (collapsed: unknown, options?: ChangeOptions<SidebarCollapsedChangeReason>) => {
      if (typeof collapsed !== "boolean") throw new TypeError("setCollapsed takes true or false.")
      if (collapsed === context.store.get().collapsed) return false
      return change("collapsed", collapsed, reasonOf(options))
    }
    return {
      setCollapsed,
      collapse: (options?: ChangeOptions<SidebarCollapsedChangeReason>) => setCollapsed(true, options),
      expand: (options?: ChangeOptions<SidebarCollapsedChangeReason>) => setCollapsed(false, options),
      toggle: (options?: ChangeOptions<SidebarCollapsedChangeReason>) =>
        setCollapsed(!context.store.get().collapsed, options),
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "navigation",
      attrs: (state) => ({ "data-collapsed": state.collapsed ? "" : undefined }),
    }),
    trigger: slot({
      attrs: (state) => ({
        type: "button",
        "aria-expanded": String(!state.collapsed),
        "data-collapsed": state.collapsed ? "" : undefined,
      }),
      press: ({ api }, event) => api.toggle({ reason: "trigger-press", event }),
    }),
  }),
  agent: { actions: ["collapse", "expand", "toggle", "setCollapsed"] },
})

function createSidebarController() {
  return createController<SidebarController>()
}

export { createSidebarController, sidebar }
export type { SidebarCollapsedChangeReason, SidebarController, SidebarOptions }

"use client"

import { useMemo, useSyncExternalStore, type ComponentProps } from "react"
import { PanelLeftIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import type { SidebarController } from "@/components/ui/sidebar-primitive"
import { cn } from "@/lib/utils"

type SidebarLabels = {
  collapse: string
  expand: string
  /** A SidebarTrigger's name when it isn't told whether the sidebar is collapsed. */
  toggle: string
  open: string
  close: string
}

const sidebarLabels: SidebarLabels = {
  collapse: "Collapse sidebar",
  expand: "Expand sidebar",
  toggle: "Toggle sidebar",
  open: "Open navigation",
  close: "Close navigation",
}

const defaultNarrowQuery = "(max-width: 767px)"

function subscribeTo(query: string) {
  return (notify: () => void) => {
    if (typeof matchMedia !== "function") return () => {}
    const list = matchMedia(query)
    list.addEventListener("change", notify)
    return () => list.removeEventListener("change", notify)
  }
}

// The server and the first client render assume a wide screen, so hydration matches before the query runs.
function useNarrow(query: string) {
  const subscribe = useMemo(() => subscribeTo(query), [query])
  return useSyncExternalStore(
    subscribe,
    () => typeof matchMedia === "function" && matchMedia(query).matches,
    () => false,
  )
}

type DrawerState = { open: boolean; listeners: Set<() => void> }

// The sidebar's controller drives the collapsed rail, which UI SDK binds to the mounted <nav>. On narrow screens that
// <nav> lives inside a closed drawer, so a SidebarTrigger elsewhere opens the drawer through this state, keyed by the
// same controller, instead.
const drawers = new WeakMap<SidebarController, DrawerState>()

function drawerOf(controller: SidebarController) {
  let state = drawers.get(controller)
  if (!state) {
    state = { open: false, listeners: new Set() }
    drawers.set(controller, state)
  }
  return state
}

function setSidebarDrawerOpen(controller: SidebarController, open: boolean) {
  const state = drawerOf(controller)
  if (state.open === open) return
  state.open = open
  for (const listener of state.listeners) listener()
}

const noController: SidebarController = {
  setCollapsed: () => undefined,
  collapse: () => undefined,
  expand: () => undefined,
  toggle: () => undefined,
}

/**
 * Whether the narrow-screen drawer of the Sidebar with this controller is open. With `closeWhenWide`, the narrow
 * query, the drawer closes when the screen leaves it, so it doesn't reopen on the way back.
 */
function useSidebarDrawerOpen(controller: SidebarController | undefined, closeWhenWide?: string) {
  const state = drawerOf(controller ?? noController)
  const subscribe = useMemo(
    () => (notify: () => void) => {
      state.listeners.add(notify)
      const media = closeWhenWide && typeof matchMedia === "function" ? matchMedia(closeWhenWide) : undefined
      const onChange = () => {
        if (controller && !media?.matches) setSidebarDrawerOpen(controller, false)
      }
      media?.addEventListener("change", onChange)
      return () => {
        state.listeners.delete(notify)
        media?.removeEventListener("change", onChange)
      }
    },
    [state, controller, closeWhenWide],
  )
  return useSyncExternalStore(
    subscribe,
    () => state.open,
    () => false,
  )
}

type SidebarTriggerProps = Omit<ComponentProps<typeof Button>, "size" | "aria-label" | "onClick"> & {
  /** The controller passed to the Sidebar it toggles. */
  controller: SidebarController
  /** The sidebar's state, from `collapsed`/`onCollapsedChange`, for `aria-expanded` and the right name. */
  collapsed?: boolean
  labels?: Partial<SidebarLabels>
  /**
   * Match the Sidebar's. On narrow screens the trigger opens the Sidebar's drawer instead of collapsing it; give the
   * Sidebar `trigger={false}` (or `narrowTrigger={false}`) so it doesn't render a drawer button of its own.
   */
  narrowQuery?: string
}

function SidebarTrigger({
  controller,
  collapsed,
  labels: labelOverrides,
  narrowQuery = defaultNarrowQuery,
  variant = "ghost",
  className,
  ...props
}: SidebarTriggerProps) {
  const labels = { ...sidebarLabels, ...labelOverrides }
  const narrow = useNarrow(narrowQuery)
  const drawerOpen = useSidebarDrawerOpen(controller)
  if (narrow) {
    return (
      <Button
        data-slot="sidebar-trigger"
        variant={variant}
        size="icon"
        aria-label={labels.open}
        aria-haspopup="dialog"
        aria-expanded={drawerOpen}
        className={cn("rtl:[&_svg]:-scale-x-100", className)}
        onClick={() => setSidebarDrawerOpen(controller, true)}
        {...props}
      >
        <PanelIcon />
      </Button>
    )
  }
  const name = collapsed === undefined ? labels.toggle : collapsed ? labels.expand : labels.collapse
  return (
    <Button
      data-slot="sidebar-trigger"
      variant={variant}
      size="icon"
      aria-label={name}
      aria-expanded={collapsed === undefined ? undefined : !collapsed}
      className={cn("rtl:[&_svg]:-scale-x-100", className)}
      onClick={(event) => {
        controller.toggle({ reason: "trigger-press", event: event.nativeEvent })
      }}
      {...props}
    >
      <PanelLeftIcon />
    </Button>
  )
}

/** @deprecated Import `PanelLeftIcon` from `lucide-react`. */
const PanelIcon = PanelLeftIcon

export {
  defaultNarrowQuery,
  PanelIcon,
  setSidebarDrawerOpen,
  SidebarTrigger,
  sidebarLabels,
  useNarrow,
  useSidebarDrawerOpen,
}
export type { SidebarLabels, SidebarTriggerProps }

"use client"

import { createContext, use, useId, type ComponentProps, type ReactElement, type ReactNode } from "react"

import { Link, type LinkProps } from "@/components/ui/link"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

const SidebarRailContext = createContext(false)

type SidebarGroupProps = Omit<ComponentProps<"div">, "children"> & {
  /** Shown above the items and names their list. Leave it out for items that need no heading, like the first ones. */
  label?: string
  /** `muted` quiets the group's items, like sections on their way out; the current page keeps its fill. */
  tone?: "default" | "muted"
  children: ReactNode
}

function SidebarGroup({ label, tone = "default", className, children, ...props }: SidebarGroupProps) {
  const labelId = useId()
  return (
    <div
      data-slot="sidebar-group"
      data-tone={tone === "muted" ? "muted" : undefined}
      className={cn("group/sidebar-group flex flex-col gap-inline", className)}
      {...props}
    >
      {label !== undefined && (
        <div
          id={labelId}
          data-slot="sidebar-group-label"
          className="truncate px-inset-item text-xs font-medium text-muted-foreground group-data-collapsed/sidebar:sr-only"
        >
          {label}
        </div>
      )}
      <ul aria-labelledby={label === undefined ? undefined : labelId} className="flex flex-col gap-px">
        {children}
      </ul>
    </div>
  )
}

type SidebarItemProps = Omit<LinkProps, "children" | "current" | "variant" | "render"> & {
  icon?: ReactNode
  current?: boolean
  badge?: ReactNode
  render?: ReactElement<Record<string, unknown>>
  children: string
}

const itemClassName =
  "flex h-control w-full min-w-0 pointer-coarse:h-(--control-height-touch) items-center gap-inline rounded-control px-inset-item text-sm font-medium text-foreground outline-none transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:ring-2 focus-visible:ring-ring aria-[current=page]:bg-primary aria-[current=page]:text-primary-foreground group-data-[tone=muted]/sidebar-group:not-aria-[current=page]:text-muted-foreground group-data-collapsed/sidebar:justify-center group-data-collapsed/sidebar:px-0 [&_svg]:size-4 [&_svg]:shrink-0"

function SidebarItem({ icon, current = false, badge, render, className, children, ...props }: SidebarItemProps) {
  const rail = use(SidebarRailContext)
  const linkProps = {
    "data-slot": "sidebar-item",
    "data-current": current ? "" : undefined,
    current,
    variant: "plain" as const,
    className: cn(itemClassName, className),
    ...props,
  }
  const content = (
    <>
      {icon}
      <span className="min-w-0 flex-1 truncate group-data-collapsed/sidebar:sr-only">{children}</span>
      {badge !== undefined && <span className="ms-auto text-xs group-data-collapsed/sidebar:hidden">{badge}</span>}
    </>
  )
  return (
    <li data-slot="sidebar-item-container">
      {rail ? (
        <Tooltip type="label">
          <TooltipTrigger render={<Link {...linkProps} render={render} />}>{content}</TooltipTrigger>
          <TooltipContent side="right">{children}</TooltipContent>
        </Tooltip>
      ) : (
        <Link {...linkProps} render={render}>
          {content}
        </Link>
      )}
    </li>
  )
}

export { SidebarGroup, SidebarItem, SidebarRailContext }
export type { SidebarGroupProps, SidebarItemProps }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { useMemo, useState, useSyncExternalStore } from "react"

import {
  createSidebarController,
  type SidebarCollapsedChangeReason,
  type SidebarController,
} from "@/components/ui/sidebar-primitive"

type SidebarStateOptions = {
  /** Remembers the collapsed state in localStorage under this key, across reloads and tabs. */
  storageKey?: string
  defaultCollapsed?: boolean
}

type SidebarState = {
  controller: SidebarController
  collapsed: boolean
  setCollapsed: (collapsed: boolean) => void
  /** Spread on the Sidebar. */
  sidebarProps: {
    controller: SidebarController
    collapsed: boolean
    onCollapsedChange: (collapsed: boolean, details: ChangeDetails<SidebarCollapsedChangeReason>) => void
  }
  /** Spread on the SidebarTrigger that toggles it, like one in a Topbar's `leading`. */
  triggerProps: { controller: SidebarController; collapsed: boolean }
}

const listeners = new Map<string, Set<() => void>>()

// Storage can throw (blocked site data, a sandboxed frame); the sidebar then just doesn't remember.
function readStored(key: string): boolean | undefined {
  let value: string | null = null
  try {
    value = localStorage.getItem(key)
  } catch {
    return undefined
  }
  return value === null ? undefined : value === "collapsed"
}

function writeStored(key: string, collapsed: boolean) {
  try {
    localStorage.setItem(key, collapsed ? "collapsed" : "expanded")
  } catch {
    // Not remembered, still applied for this page.
  }
  for (const listener of listeners.get(key) ?? []) listener()
}

function subscribeTo(key: string) {
  return (notify: () => void) => {
    const own = listeners.get(key) ?? new Set()
    listeners.set(key, own)
    own.add(notify)
    const onStorage = (event: StorageEvent) => {
      if (event.key === key) notify()
    }
    addEventListener("storage", onStorage)
    return () => {
      own.delete(notify)
      removeEventListener("storage", onStorage)
    }
  }
}

const noStorage = () => () => {}

/**
 * A sidebar's controller and collapsed state for a Sidebar and the SidebarTrigger that toggles it, remembered under
 * `storageKey`. The server and the first client render use `defaultCollapsed`, so hydration matches.
 */
function useSidebarState({ storageKey, defaultCollapsed = false }: SidebarStateOptions = {}): SidebarState {
  const [controller] = useState(createSidebarController)
  const [own, setOwn] = useState(defaultCollapsed)
  const subscribe = useMemo(() => (storageKey === undefined ? noStorage : subscribeTo(storageKey)), [storageKey])
  const stored = useSyncExternalStore(
    subscribe,
    () => (storageKey === undefined ? undefined : readStored(storageKey)),
    () => undefined,
  )
  const collapsed = storageKey === undefined ? own : (stored ?? defaultCollapsed)
  const setCollapsed = (next: boolean) => (storageKey === undefined ? setOwn(next) : writeStored(storageKey, next))
  return {
    controller,
    collapsed,
    setCollapsed,
    sidebarProps: {
      controller,
      collapsed,
      onCollapsedChange: (next, details) => {
        if (!details.canceled) setCollapsed(next)
      },
    },
    triggerProps: { controller, collapsed },
  }
}

export { useSidebarState }
export type { SidebarState, SidebarStateOptions }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { createParts } from "@ui-sdk/react/primitive"
import { useState, type ReactNode } from "react"
import { PanelLeftIcon, XIcon } from "lucide-react"

import { buttonVariants } from "@/components/ui/button"
import { Drawer, DrawerBackdrop, DrawerClose, DrawerContent, DrawerTitle, DrawerTrigger } from "@/components/ui/drawer"
import {
  createSidebarController,
  sidebar,
  type SidebarCollapsedChangeReason,
  type SidebarController,
} from "@/components/ui/sidebar-primitive"
import {
  SidebarGroup,
  SidebarItem,
  SidebarRailContext,
  type SidebarGroupProps,
  type SidebarItemProps,
} from "@/components/ui/sidebar-items"
import {
  defaultNarrowQuery,
  setSidebarDrawerOpen,
  SidebarTrigger,
  sidebarLabels,
  useNarrow,
  useSidebarDrawerOpen,
  type SidebarLabels,
  type SidebarTriggerProps,
} from "@/components/ui/sidebar-trigger"
import { ControlTooltip } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import { useSidebarState, type SidebarState, type SidebarStateOptions } from "@/components/ui/use-sidebar-state"

const { Root: SidebarRoot, Trigger: SidebarToggle } = createParts(sidebar, { root: "nav", trigger: "button" })

type SidebarProps = {
  label: string
  collapsed?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean, details: ChangeDetails<SidebarCollapsedChangeReason>) => void
  collapsible?: boolean
  /**
   * What collapsing does on wide screens: `rail` keeps the items as icons with tooltips; `hide` slides the sidebar
   * away, for items without icons, like a docs sidebar. Hidden, it has no toggle of its own, so pair it with a
   * SidebarTrigger elsewhere.
   */
  collapse?: "rail" | "hide"
  /**
   * `false` when a SidebarTrigger elsewhere, like in a Topbar's `leading`, takes the place of the sidebar's own
   * buttons: the collapse toggle in its header and, on narrow screens, the drawer button.
   */
  trigger?: boolean
  /** Whether the sidebar renders its drawer button on narrow screens. Follows `trigger` by default. */
  narrowTrigger?: boolean
  controller?: SidebarController
  narrowQuery?: string
  header?: ReactNode
  footer?: ReactNode
  labels?: Partial<SidebarLabels>
  className?: string
  children: ReactNode
}

const surfaceClassName = "flex min-h-0 flex-col gap-group text-foreground"

function Sidebar({
  label,
  collapsed: collapsedProp,
  defaultCollapsed = false,
  onCollapsedChange,
  collapsible = true,
  collapse = "rail",
  controller,
  narrowQuery = defaultNarrowQuery,
  trigger = true,
  narrowTrigger = trigger,
  header,
  footer,
  labels: labelOverrides,
  className,
  children,
}: SidebarProps) {
  const labels = { ...sidebarLabels, ...labelOverrides }
  const narrow = useNarrow(narrowQuery)
  const [ownCollapsed, setOwnCollapsed] = useState(defaultCollapsed)
  const [ownDrawerOpen, setOwnDrawerOpen] = useState(false)
  const sharedDrawerOpen = useSidebarDrawerOpen(controller, narrowQuery)
  const drawerOpen = controller ? sharedDrawerOpen : ownDrawerOpen
  const setDrawerOpen = (open: boolean) =>
    controller ? setSidebarDrawerOpen(controller, open) : setOwnDrawerOpen(open)
  const collapsed = collapsible && !narrow && (collapsedProp ?? ownCollapsed)
  const rail = collapsed && collapse === "rail"

  const body = <div className="flex min-h-0 flex-1 flex-col gap-group overflow-y-auto">{children}</div>

  if (narrow) {
    return (
      <Drawer side="start" open={drawerOpen} onOpenChange={setDrawerOpen}>
        {narrowTrigger && (
          <DrawerTrigger variant="ghost" size="icon" aria-label={labels.open} className={className}>
            <PanelLeftIcon />
          </DrawerTrigger>
        )}
        <DrawerBackdrop />
        <DrawerContent
          className="gap-group p-items"
          onClickCapture={(event) => {
            if (event.target instanceof Element && event.target.closest("a[href]")) setDrawerOpen(false)
          }}
        >
          <div className="flex items-center gap-inline">
            <DrawerTitle className="flex-1 truncate px-inset-item text-base">{label}</DrawerTitle>
            <DrawerClose variant="ghost" size="icon" aria-label={labels.close}>
              <XIcon />
            </DrawerClose>
          </div>
          <SidebarRoot aria-label={label} collapsed={false} className={cn(surfaceClassName, "flex-1")}>
            {header}
            {body}
            {footer}
          </SidebarRoot>
        </DrawerContent>
      </Drawer>
    )
  }

  return (
    <SidebarRoot
      aria-label={label}
      data-collapse={collapse}
      collapsed={collapsed}
      controller={controller}
      onCollapsedChange={(next, details) => {
        onCollapsedChange?.(next, details)
        if (!details.canceled) setOwnCollapsed(next)
      }}
      className={cn(
        surfaceClassName,
        "group/sidebar h-full w-(--sidebar-width) shrink-0 overflow-hidden border-e bg-muted/(--glass-opacity) p-items backdrop-surface transition-all duration-panel ease-standard data-collapsed:w-(--sidebar-rail-width) motion-reduce:transition-none",
        collapse === "hide" &&
          "data-collapsed:invisible data-collapsed:w-0 data-collapsed:border-e-0 data-collapsed:px-0",
        className,
      )}
    >
      <div data-slot="sidebar-header" className="flex items-center gap-inline group-data-collapsed/sidebar:flex-col">
        <div className="min-w-0 flex-1 group-data-collapsed/sidebar:hidden">{header}</div>
        {collapsible && trigger && (
          <ControlTooltip label={collapsed ? labels.expand : labels.collapse}>
            <SidebarToggle
              aria-label={collapsed ? labels.expand : labels.collapse}
              className={cn(buttonVariants({ variant: "ghost", size: "icon" }), "rtl:[&_svg]:-scale-x-100")}
            >
              <PanelLeftIcon />
            </SidebarToggle>
          </ControlTooltip>
        )}
      </div>
      <SidebarRailContext value={rail}>{body}</SidebarRailContext>
      {footer !== undefined && (
        <div data-slot="sidebar-footer" className="group-data-collapsed/sidebar:hidden">
          {footer}
        </div>
      )}
    </SidebarRoot>
  )
}

export { createSidebarController, Sidebar, SidebarGroup, SidebarItem, sidebarLabels, SidebarTrigger, useSidebarState }
export type { SidebarState, SidebarStateOptions }
export type { SidebarController, SidebarLabels, SidebarProps }
export type { SidebarTriggerProps }
export type { SidebarGroupProps, SidebarItemProps }
